using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
public static class RuinsOrnamentReview{
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static Color32[] Shot(Camera c,Vector3 from,Vector3 target,string file){c.transform.position=from;c.transform.LookAt(target);var rt=new RenderTexture(1200,900,24);c.targetTexture=rt;for(int i=0;i<3;i++)c.Render();Check(!ShaderUtil.ShaderHasError(Shader.Find("MapRuins/AgedLimestone")),"Rendered shader compilation failed");var prev=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(1200,900,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1200,900),0,0);t.Apply();File.WriteAllBytes(file,t.EncodeToPNG());var pixels=t.GetPixels32();RenderTexture.active=prev;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(rt);return pixels;}
 public static void Run(){const string ev="Evidence/Target28Ornament";Directory.CreateDirectory(ev);try{
 EditorSceneManager.OpenScene("Assets/RuinsTarget28Output/Room.unity");var current=GameObject.Find("ruins_1").transform.parent.gameObject;var baseline=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget23Output/Structures/Ruins.prefab"));Check(baseline!=null,"Undecorated baseline missing");
 var c=UnityEngine.Object.FindAnyObjectByType<Camera>();c.orthographic=false;c.backgroundColor=new Color(.075f,.085f,.1f);RenderSettings.ambientLight=Color.gray*.65f;var sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).First(l=>l.type==LightType.Directional);sun.transform.rotation=Quaternion.Euler(38,-28,0);
 var hidden=new[]{5,6,10,13,20,21,22,25,26,27}.Select(i=>"ruins_"+i).ToArray();foreach(var root in new[]{current,baseline})foreach(var id in hidden)root.transform.Find(id).gameObject.SetActive(false);
 current.SetActive(false);baseline.SetActive(true);var plainBefore=Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/plain-before.png");baseline.SetActive(false);current.SetActive(true);var plainAfter=Shot(c,new Vector3(15,20,19),new Vector3(0,3.5f,0),ev+"/plain-after.png");Check(plainBefore.SequenceEqual(plainAfter),"Undecorated geometry/material pixel regression");foreach(var root in new[]{current,baseline})foreach(var id in hidden)root.transform.Find(id).gameObject.SetActive(true);
 var names=new[]{"room","wall","pier","arch","paving"};var from=new[]{new Vector3(15,20,19),new Vector3(-9,6,4),new Vector3(1,6,9),new Vector3(13,7,5),new Vector3(-11,6,5)};var at=new[]{new Vector3(0,3.5f,0),new Vector3(-4,4.2f,0),new Vector3(-1.5f,4.5f,6),new Vector3(8,4.7f,0),new Vector3(-8,3.05f,0)};
 for(int i=0;i<names.Length;i++){current.SetActive(false);baseline.SetActive(true);Shot(c,from[i],at[i],ev+"/"+names[i]+"-before.png");baseline.SetActive(false);current.SetActive(true);Shot(c,from[i],at[i],ev+"/"+names[i]+"-after.png");}
 // Isolate one wall: previous carved shader versus revised shader, identical geometry/camera/light.
 baseline.SetActive(false);current.SetActive(true);foreach(Transform child in current.transform)child.gameObject.SetActive(child.name=="ruins_10");
 var wall=current.transform.Find("ruins_10").GetComponent<MeshRenderer>();var finalMat=wall.sharedMaterial;var oldMat=new Material(finalMat);oldMat.shader=Shader.Find("MapRuins/OrnamentBefore27");Check(oldMat.shader!=null,"Previous shader missing");
 var oldRoot=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget26Output/Structures/Ruins.prefab"));
 foreach(Transform child in oldRoot.transform)child.gameObject.SetActive(child.name=="ruins_10");var oldWall=oldRoot.transform.Find("ruins_10").GetComponent<MeshRenderer>();oldWall.sharedMaterial=oldMat;oldRoot.SetActive(false);
 var centre=wall.bounds.center;c.orthographic=true;c.orthographicSize=3.6f;
 wall.gameObject.SetActive(false);oldRoot.SetActive(true);Shot(c,centre+new Vector3(8,6,4),centre,ev+"/wall-isolated-before.png");
 oldRoot.SetActive(false);wall.gameObject.SetActive(true);wall.sharedMaterial=finalMat;Shot(c,centre+new Vector3(8,6,4),centre,ev+"/wall-isolated-after.png");
 c.orthographicSize=1.65f;wall.gameObject.SetActive(false);oldRoot.SetActive(true);Shot(c,centre+new Vector3(4,1.3f,2),centre,ev+"/wall-isolated-close-before.png");
 oldRoot.SetActive(false);wall.gameObject.SetActive(true);wall.sharedMaterial=finalMat;Shot(c,centre+new Vector3(4,1.3f,2),centre,ev+"/wall-isolated-close-after.png");
 sun.transform.rotation=Quaternion.Euler(25,140,0);c.orthographicSize=3.6f;Shot(c,centre+new Vector3(8,6,4),centre,ev+"/wall-isolated-opposite.png");
 UnityEngine.Object.DestroyImmediate(oldRoot);UnityEngine.Object.DestroyImmediate(oldMat);foreach(Transform child in current.transform)child.gameObject.SetActive(true);c.orthographic=false;
 sun.transform.rotation=Quaternion.Euler(25,140,0);Shot(c,from[0],at[0],ev+"/opposite.png");
 var carved=current.GetComponentsInChildren<MeshRenderer>().Where(r=>r.sharedMaterial.IsKeywordEnabled("_RUINS_ORNAMENT")).ToArray();Check(carved.Length==10,"Decorated instance count");Check(carved.Select(r=>r.sharedMaterial).Distinct().Count()==1,"Carved material sharing");
 foreach(var r in carved){var mesh=r.GetComponent<MeshFilter>().sharedMesh;Check(mesh==r.GetComponent<MeshCollider>().sharedMesh,"Collider identity");Check(mesh.uv.Any(v=>v.x< -96),"Missing relief UV domain");}
 foreach(var id in new[]{"ruins_6","ruins_20","ruins_22","ruins_26"}){var template=current.transform.Find(id).gameObject;foreach(int count in new[]{9,225}){var clones=Enumerable.Range(0,count).Select(i=>{var go=UnityEngine.Object.Instantiate(template);go.transform.position=new Vector3(100+i*5,3,100);return go;}).ToArray();Check(clones.Select(g=>g.GetComponent<MeshFilter>().sharedMesh).Distinct().Count()==1&&clones.Select(g=>g.GetComponent<MeshRenderer>().sharedMaterial).Distinct().Count()==1,"Shared decorated resources");foreach(var go in clones)UnityEngine.Object.DestroyImmediate(go);}}
 File.WriteAllText(ev+"/result.json","{\"pass\":true,\"decoratedFamilies\":4,\"instances\":10,\"sameCameraBeforeAfter\":true,\"undecoratedPixelDelta\":0,\"shared9And225\":true,\"colliderIdentity\":true,\"GPUMeasured\":false}");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(ev+"/failure.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
